<header class="section-heading"><div><span class="status">Alunos</span><h1>Consultar</h1><p class="meta">Todos os alunos ativos, seus cursos e o estado das integrações.</p></div><a class="button-primary" href="<?= $escape($basePath) ?>/finance/customers/create"><i class="fa-solid fa-user-plus" aria-hidden="true"></i> Novo aluno</a></header>
<form method="get" action="<?= $escape($basePath) ?>/students" class="contact-filters"><input name="q" value="<?= $escape($search) ?>" placeholder="Nome, e-mail, CPF ou usuário do AVA"><button type="submit">Pesquisar</button><?php if($search!==''):?><a class="button-secondary" href="<?= $escape($basePath) ?>/students">Limpar</a><?php endif;?></form>
<section class="card"><div class="table-responsive"><table><thead><tr><th>Aluno</th><th>CPF</th><th>Cursos</th><th>Unidade</th><th>Integrações</th></tr></thead><tbody><?php if($students===[]):?><tr><td colspan="5">Nenhum aluno ativo encontrado.</td></tr><?php endif;?><?php foreach($students as$student):$courses=array_values(array_filter(explode('||',(string)($student['active_course_names']??''))));?><tr><td><a href="<?= $escape($basePath) ?>/finance/customers/<?= (int)$student['id'] ?>"><strong><?= $escape($student['name']) ?></strong></a><br><small><?= $escape($student['email']?:'Sem e-mail') ?></small></td><td><?= $escape($student['cpf_cnpj']?:'Não informado') ?></td><td><?php if($courses===[]):?><span class="meta">Nenhum curso ativo</span><?php else:?><div class="student-course-list"><?php foreach($courses as$course):?><span><i class="fa-solid fa-book-open" aria-hidden="true"></i> <?= $escape($course) ?></span><?php endforeach;?></div><?php endif;?></td><td><i class="fa-solid fa-building" aria-hidden="true"></i> <?= $escape($student['unit_name']?:'Sem unidade') ?></td><td><div class="student-integrations"><span class="connection-badge <?= $student['asaas_customer_id']?'connection-connected':'connection-rejected' ?>" title="Integração Asaas"><i class="fa-solid fa-wallet" aria-hidden="true"></i> Asaas <?= $student['asaas_customer_id']?'vinculado':'pendente' ?></span><span class="connection-badge <?= (int)$student['moodle_linked']===1?'connection-connected':'connection-awaiting_official_api' ?>" title="Integração com o AVA"><i class="fa-solid fa-graduation-cap" aria-hidden="true"></i> AVA <?= (int)$student['moodle_linked']===1?'vinculado':($student['moodle_user_id']?'em revisão':'pendente') ?></span><a class="button-secondary button-small finance-icon-button" href="<?= $escape($basePath) ?>/finance/customers/<?= (int)$student['id'] ?>" title="Abrir cadastro" aria-label="Abrir cadastro"><i class="fa-solid fa-eye" aria-hidden="true"></i></a></div></td></tr><?php endforeach;?></tbody></table></div></section>
